__NUXT_JSONP__("/ar/how-to-apply/others", {data:[{details:{slug:"ar",pageTitle:"الآخرين | Mentor Language Institute",pageDescription:"نشكر لك إهتمامك بالإلتحاق بمعهد مينتور هذه الصفحة لمن يحملون فيزا أخرى غير فيزا الطالب, أو للمواطنين من دول ال ESTA أو لمن يحملون فيزا سياحية",title:"الآخرين",image:"\u002Fimages\u002Fhow-to-apply\u002Fapply-others\u002Fapply-others.jpg",subtitle:["نشكر لك إهتمامك بالإلتحاق بمعهد مينتور\u003Cbr \u002F\u003Eهذه الصفحة لمن يحملون فيزا أخرى غير فيزا الطالب, أو للمواطنين من دول ال ESTA أو لمن يحملون فيزا سياحية","إذا كنت ترغب التقدم إلى منتور بدون فيزا اف1 الدراسية, الرجاء اكمال خطوات الإلتحاق بالمعهد في هذه الصفحة"],applyOnline:{imageLink:{image:"\u002Fimages\u002Fcommon\u002Fapply-now-ar.png",link:"\u002Far\u002Fadmission"}},applicationSteps:{title:"خطوات الأبلكيشن",description:["خطوات الأبلكيشن سوف تختلف بناء على بلدك و جنسيتك و الدورة المراد الإلتحاق بها و نوع الفيزا ,,الخ  موظفينا سوف يقومون بمساعدتك و إرشادك بالخطوات المحددة بعد قيامك بتقديم الأبلكيشن أونلاين"]},needHelp:{title:"تحتاج المزيد من المساعدة؟ إسألنا",description:["- هل بإمكاني الدراسة في معهد مينتور بدون فيزا طالب\u003Cbr \u002F\u003E- هل بإمكاني الإلتحاق بمعهد مينتور بأي فيزا أخرى غير فيزا الطالب F1\u003Cbr \u002F\u003E- كم المدة التي يمكنني البقاء بها في الولايات المتحدة بدون فيزا طالب؟\u003Cbr \u002F\u003E- كم عدد الساعات في الأسبوع التي يتوجب علي دراستها في منتور في حال الحصول على فيزا طالب","الأجوبة لهذه الأسئلة كلها موضحة في الموقع الرئيسي للسفارة الأمريكية وفي موقع مكتب الهجرة.","إن كنت ترغب المزيد من التوضيح قبل تقديم الأبلكيشن الرجاء التحقق بالاطلاع على الموقع أو التواصل معنا. سوف نقدم لك الإستشارة بثمانية لغات مختلفة"]},contactUs:{image:"\u002Fimages\u002Fcommon\u002Fcontact-us-ar.png",link:"\u002Far\u002Fcontact",title:"اتصل بنا",lists:[{campus:"＜WESTWOOD CAMPUS＞",address:"10880 Wilshire Blvd., Suite #122, Los Angeles, CA 90024",telephone:"Tel:310⁻887⁻0777"},{campus:"＜HOLLYWOOD CAMPUS＞",address:"7080 Hollywood Blvd., Suite 314 Los Angeles, CA 90028",telephone:"Tel:323⁻870⁻7102"}]},dir:"\u002Fothers",path:"\u002Fothers\u002Far",extension:".json",createdAt:"2026-10-22T16:31:30.012Z",updatedAt:"2025-05-26T12:06:27.832Z"}}],fetch:{},mutations:void 0});